  -- source id: 8
  (
    'dd000001-0008-4000-8000-000000000001',
    'ARIZONA@WORK — Statewide Network',
    'ARIZONA@WORK is the statewide workforce development network operated through the Arizona Department of Economic Security, connecting job seekers in all 15 counties to career coaching, resume assistance, WIOA training referrals, and fair-chance employment navigation. Justice-involved adults leaving ADCRR custody or county jails can register at arizonaatwork.com for free core services at local one-stop centers. Workforce services—not emergency cash or housing placement.',
    'ARIZONA@WORK es la red estatal de desarrollo de la fuerza laboral operada por el Departamento de Seguridad Económica de Arizona, conectando buscadores de empleo en los 15 condados con coaching de carrera, asistencia con currículum y referencias de capacitación WIOA. Los adultos con antecedentes penales pueden registrarse en arizonaatwork.com para servicios básicos gratuitos.',
    'c1000001-0003-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '1789 W Jefferson Street',
    '602-771-6500',
    'https://arizonaatwork.com',
    NULL,
    'One-stop centers typically Monday–Friday business hours',
    'Open to Arizona job seekers including justice-involved individuals; core ARIZONA@WORK services are free.',
    'Abierto a buscadores de empleo de Arizona incluidas personas con antecedentes penales; servicios básicos gratuitos.',
    'Register at arizonaatwork.com; find your local one-stop by ZIP code; pairs with DES benefits and RSA vocational rehabilitation.',
    'Regístrese en arizonaatwork.com; encuentre su centro local por código postal; se vincula con beneficios DES y rehabilitación vocacional RSA.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Career coaching', 'Resume assistance', 'WIOA training referrals', 'Job search tools', 'Fair-chance employment navigation'],
    ARRAY['statewide', 'employment', 'arizona-at-work', 'WIOA', 'fair-chance', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 9
  (
    'dd000001-0009-4000-8000-000000000001',
    'RSA — Vocational Rehabilitation Services',
    'The Rehabilitation Services Administration within Arizona DES helps Arizonans with disabilities—including justice-involved individuals with documented disabilities—prepare for, obtain, and maintain employment through counseling, training, assistive technology, and job placement across all 15 counties. VR counselors coordinate with ARIZONA@WORK, AHCCCS behavioral health providers, and ADCRR reentry staff on individualized employment plans. VR eligibility requires a documented disability affecting employment—not general reentry case management.',
    'La Administración de Servicios de Rehabilitación dentro de DES de Arizona ayuda a arizonenses con discapacidades—incluidas personas con antecedentes penales con discapacidades documentadas—a prepararse, obtener y mantener empleo a través de consejería, capacitación y colocación laboral en los 15 condados. La elegibilidad VR requiere una discapacidad documentada que afecte el empleo.',
    'c1000001-0003-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '1789 W Jefferson Street',
    '602-542-3332',
    'https://des.az.gov/services/employment/rehabilitation-services',
    NULL,
    'State and field offices Monday–Friday business hours',
    'Arizona residents with a physical or mental disability that is a substantial barrier to employment; justice-involved applicants welcome if VR eligible.',
    'Residentes de Arizona con una discapacidad física o mental que sea una barrera sustancial al empleo; solicitantes con antecedentes penales bienvenidos si son elegibles para VR.',
    'Apply at des.az.gov RSA or through local VR office; call 602-542-3332; coordinate with ARIZONA@WORK for job placement after plan approval.',
    'Solicite en des.az.gov RSA o en la oficina VR local; llame al 602-542-3332; coordine con ARIZONA@WORK después de aprobar el plan.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Vocational counseling', 'Disability employment planning', 'Training referrals', 'Assistive technology', 'Job placement'],
    ARRAY['statewide', 'employment', 'vocational-rehabilitation', 'disability', 'RSA', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 10
  (
    'dd000001-0010-4000-8000-000000000001',
    'AHCCCS — RBHA Behavioral Health Directory',
    'Arizona''s Regional Behavioral Health Authorities contract with AHCCCS to deliver mental health and substance use disorder services for Medicaid members and uninsured crisis populations in six regions covering all 15 counties. Justice-involved Arizonans can locate their RBHA—Mercy Care, Banner, Health Choice, Cenpatico, Arizona Complete Health, or Steward—at azahcccs.gov to access outpatient treatment, crisis services, and peer support. Directory and enrollment navigation—not a single treatment facility.',
    'Las Autoridades Regionales de Salud Conductual de Arizona contratan con AHCCCS para ofrecer servicios de salud mental y trastornos por uso de sustancias para miembros Medicaid en seis regiones que cubren los 15 condados. Los arizonenses en reinserción pueden localizar su RBHA en azahcccs.gov para acceder a tratamiento ambulatorio, servicios de crisis y apoyo entre pares.',
    'c1000001-0005-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '801 E Jefferson Street',
    '602-417-4000',
    'https://www.azahcccs.gov/Members/GetCovered/Crisis.html',
    NULL,
    'Crisis lines 24/7; RBHA offices business hours',
    'AHCCCS members and crisis-eligible uninsured individuals; SUD and mental health services vary by RBHA region and plan.',
    'Miembros AHCCCS e individuos sin seguro elegibles para crisis; los servicios varían por región RBHA y plan.',
    'Find your RBHA at azahcccs.gov; crisis line 1-844-534-4673; enroll in AHCCCS through healthearizonaplus.gov first when eligible.',
    'Encuentre su RBHA en azahcccs.gov; línea de crisis 1-844-534-4673; inscríbase en AHCCCS a través de healthearizonaplus.gov cuando sea elegible.',
    ARRAY[]::TEXT[],
    'statewide',
