  -- source id: 11
  (
    'dd000001-0011-4000-8000-000000000001',
    'Arizona Department of Veterans'' Services',
    'The Arizona Department of Veterans'' Services helps veterans and their families access federal VA benefits, state tuition waivers, employment preferences, and burial honors through benefits counselors at the Phoenix headquarters and county veterans service offices in every county. Justice-involved veterans can request benefits assistance and referrals to VA medical centers, SSVF housing providers, and ARIZONA@WORK veteran staff after release. Benefits counseling and referrals—not emergency housing or cash assistance.',
    'El Departamento de Veteranos de Arizona ayuda a veteranos y sus familias a acceder a beneficios federales VA, exenciones de matrícula estatal y preferencias de empleo a través de consejeros en la sede de Phoenix y oficinas de servicios para veteranos del condado. Los veteranos en reinserción pueden solicitar asistencia de beneficios y referencias a centros médicos VA.',
    'c1000001-0014-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '700 W Washington Street',
    '602-542-8811',
    'https://dvs.az.gov',
    NULL,
    'State office Monday–Friday business hours; CVSO hours vary by county',
    'Arizona veterans, service members, and eligible family members; discharge status and benefit type determine services.',
    'Veteranos de Arizona, miembros del servicio y familiares elegibles; el estado de baja y tipo de beneficio determinan los servicios.',
    'Visit dvs.az.gov; call 602-542-8811; find your county veterans service officer through the DVS locator.',
    'Visite dvs.az.gov; llame al 602-542-8811; encuentre su oficial de servicios para veteranos del condado en el localizador DVS.',
    ARRAY[]::TEXT[],
    'statewide',
