  -- source id: 12
  (
    'dd000001-0012-4000-8000-000000000001',
    'Arizona MVD — azmvdnow.gov',
    'The Arizona Motor Vehicle Division issues state ID cards and driver''s licenses through azmvdnow.gov and MVD offices statewide, a critical step for justice-involved Arizonans reestablishing identification after release. Many MVD services including ID card renewal and address changes can be completed online; first-time IDs and reinstatements may require an office visit with proof of identity and residency. MVD issues credentials—not legal name change or birth certificate services.',
    'La División de Vehículos Motorizados de Arizona emite tarjetas de identificación estatal y licencias de conducir a través de azmvdnow.gov y oficinas MVD en todo el estado, un paso crítico para arizonenses en reinserción que restablecen identificación después de la liberación. Muchos servicios MVD pueden completarse en línea; las identificaciones por primera vez pueden requerir visita a oficina.',
    'c1000001-0008-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '100 N 15th Avenue',
    '602-255-0072',
    'https://azmvdnow.gov',
    NULL,
    'Online 24/7; office hours vary by location',
    'Arizona residents seeking state ID or driver''s license; specific documents required for first issuance after incarceration.',
    'Residentes de Arizona que buscan identificación estatal o licencia de conducir; se requieren documentos específicos para primera emisión después de encarcelación.',
    'Start at azmvdnow.gov; call 602-255-0072; bring certified birth certificate or passport plus two proofs of Arizona residency.',
    'Comience en azmvdnow.gov; llame al 602-255-0072; traiga acta de nacimiento certificada o pasaporte más dos comprobantes de residencia en Arizona.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['State ID issuance', 'Driver license services', 'Online credential renewal', 'Reinstatement guidance', 'Third-party office locator'],
    ARRAY['statewide', 'id-documentation', 'MVD', 'drivers-license', 'state-id', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 13
  (
    'dd000001-0013-4000-8000-000000000001',
    'ADHS — Office of Vital Records',
    'The Arizona Department of Health Services Office of Vital Records issues certified birth and death certificates needed for state ID, employment, and benefits applications across Arizona. Returning citizens who lack identity documents can order certified copies online, by mail, or in person at the Phoenix office with acceptable identification or qualified applicant rules. Vital records issuance—not a legal aid or MVD licensing office.',
    'La Oficina de Registros Vitales del Departamento de Servicios de Salud de Arizona emite actas de nacimiento y defunción certificadas necesarias para identificación estatal, empleo y solicitudes de beneficios. Los ciudadanos que regresan sin documentos de identidad pueden solicitar copias certificadas en línea, por correo o en persona en la oficina de Phoenix.',
    'c1000001-0008-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '1818 W Adams Street',
    '602-364-1300',
    'https://www.azdhs.gov/licensing/vital-records',
    NULL,
    'Office Monday–Friday business hours; online ordering 24/7',
    'Individuals with legal right to request vital records per Arizona law; qualified applicants may order for others with documentation.',
    'Personas con derecho legal a solicitar registros vitales según la ley de Arizona; solicitantes calificados pueden pedir para otros con documentación.',
    'Order online at azdhs.gov vital records; call 602-364-1300; first-time requests may take 2–3 weeks by mail.',
    'Solicite en línea en azdhs.gov registros vitales; llame al 602-364-1300; las primeras solicitudes pueden tardar 2–3 semanas por correo.',
    ARRAY[]::TEXT[],
    'statewide',
