  (
    'dd000001-0014-4000-8000-000000000001',
    '988 Suicide & Crisis Lifeline',
    'The 988 Suicide & Crisis Lifeline provides free, confidential 24/7 support for people in mental health, substance use, or suicidal crisis across Arizona, routing to local crisis centers and mobile teams when needed. Justice-involved individuals and families can call or text 988 for immediate emotional support and connections to RBHA crisis services—not ongoing case management or housing placement.',
    'La Línea de Crisis y Prevención del Suicidio 988 ofrece apoyo gratuito y confidencial 24/7 para personas en crisis de salud mental, uso de sustancias o suicidio en Arizona, enrutando a centros de crisis locales cuando sea necesario. Las personas con antecedentes penales y familias pueden llamar o enviar mensaje al 988 para apoyo emocional inmediato.',
    'c1000001-0015-4000-8000-000000000001',
    'Arizona',
    'Statewide',
    NULL,
    NULL,
    '988',
    'https://988lifeline.org',
    NULL,
    '24/7',
    'Anyone in mental health or suicidal crisis in the United States; Spanish-language support available.',
    'Cualquier persona en crisis de salud mental o suicida en los Estados Unidos; apoyo en español disponible.',
    'Call or text 988; chat at 988lifeline.org; veterans press 1; pairs with Arizona RBHA crisis line 1-844-534-4673.',
    'Llame o envíe mensaje al 988; chat en 988lifeline.org; veteranos presionen 1; se vincula con línea de crisis RBHA 1-844-534-4673.',
    ARRAY[]::TEXT[],
