    'SAMHSA National Helpline',
    'The SAMHSA National Helpline at 1-800-662-4357 is a free, confidential, 24/7 treatment referral service connecting callers to local substance use and mental health providers across Arizona and nationwide. Returning citizens and families can receive referrals to RBHA-contracted treatment, MAT providers, and peer support programs by ZIP code. Referral and information only—not a treatment facility or emergency housing provider.',
    'La Línea Nacional de Ayuda de SAMHSA al 1-800-662-4357 es un servicio gratuito, confidencial y 24/7 de referencia a tratamiento que conecta a personas con proveedores locales de uso de sustancias y salud mental en Arizona y a nivel nacional. Solo referencia e información, no un centro de tratamiento.',
