    'FindTreatment.gov — Arizona Locator',
    'FindTreatment.gov is SAMHSA''s searchable directory of licensed substance use and mental health treatment facilities, including outpatient, residential, and medication-assisted treatment providers across all Arizona counties. Justice-involved adults, probation officers, and reentry navigators can filter by payment options including Medicaid and justice-involved programs. Online locator only—not a crisis line or direct admission service.',
    'FindTreatment.gov es el directorio buscable de SAMHSA de centros de tratamiento licenciados de uso de sustancias y salud mental, incluidos proveedores ambulatorios, residenciales y de tratamiento asistido con medicamentos en todos los condados de Arizona. Solo localizador en línea, no línea de crisis.',
