    'dd000001-0017-4000-8000-000000000001',
    'Arizona Justice Project',
    'The Arizona Justice Project is a nonprofit law clinic that investigates claims of wrongful conviction and assists with post-conviction relief, DNA testing motions, and limited reentry legal support for incarcerated and formerly incarcerated Arizonans. Staff and law school volunteers review cases meeting project criteria—not a general legal aid office for eviction, benefits, or routine expungement.',
    'El Arizona Justice Project es una clínica legal sin fines de lucro que investiga reclamos de condena injusta y ayuda con alivio post-condena, mociones de pruebas de ADN y apoyo legal limitado de reinserción para arizonenses encarcelados y anteriormente encarcelados. No es una oficina general de ayuda legal para desalojo o beneficios.',
    'c1000001-0006-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '1102 E McKinley Street',
    '602-262-7144',
    'https://www.azjusticeproject.org',
    NULL,
    'Office Monday–Friday business hours',
    'Cases meeting Arizona Justice Project intake criteria for wrongful conviction or post-conviction claims; limited capacity.',
    'Casos que cumplan criterios de admisión del Arizona Justice Project para condena injusta o reclamos post-condena; capacidad limitada.',
    'Apply through azjusticeproject.org case inquiry form; call 602-262-7144; does not replace CLS for general civil legal aid.',
    'Solicite a través del formulario de consulta en azjusticeproject.org; llame al 602-262-7144; no reemplaza a CLS para ayuda legal civil general.',
