    'dd000001-0018-4000-8000-000000000001',
    'DES — SNAP Employment & Training (CAN)',
    'Arizona''s Connecting Arizona to Next Employment (CAN) program through DES provides SNAP Employment & Training services including job search coaching, skills training referrals, and support services for SNAP recipients statewide including justice-involved adults meeting program rules. Participants work with DES contractors and ARIZONA@WORK partners to satisfy SNAP work requirements and build employment history. E&T program—not standalone cash assistance.',
    'El programa Connecting Arizona to Next Employment (CAN) a través de DES ofrece servicios de Empleo y Capacitación SNAP incluyendo coaching de búsqueda de empleo y referencias de capacitación para beneficiarios SNAP en todo el estado incluidos adultos con antecedentes penales que cumplan las reglas del programa.',
