    'Arizona SNAP recipients referred to or enrolled in DES Employment & Training; work requirement rules apply.',
    'Beneficiarios SNAP de Arizona referidos o inscritos en Empleo y Capacitación DES; aplican reglas de requisitos de trabajo.',
    'Enroll through county DES office or ARIZONA@WORK referral; call 1-855-432-7587; pairs with healthearizonaplus.gov SNAP account.',
    'Inscríbase a través de la oficina DES del condado o referencia ARIZONA@WORK; llame al 1-855-432-7587.',
