  (
    'dd000001-0019-4000-8000-000000000001',
    'ADCRR — Community Reentry Center Overview',
    'ADCRR Community Reentry Centers provide structured transitional programming at select facilities and community sites, combining employment readiness, cognitive programming, substance use education, and community partner linkages before release to parole or community supervision. The statewide reentry center model coordinates with ARIZONA@WORK, DES, and local housing providers—not a standalone halfway house open to walk-in public intake.',
    'Los Centros de Reinserción Comunitaria de ADCRR ofrecen programación transicional estructurada en instalaciones seleccionadas y sitios comunitarios, combinando preparación laboral, programación cognitiva, educación sobre uso de sustancias y vínculos con aliados comunitarios antes de la liberación a libertad condicional. No es una casa de transición abierta al público.',
    'c1000001-0017-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '701 E Jefferson Street',
    '602-771-5500',
    'https://corrections.az.gov/adcr/community-reentry',
    NULL,
    'Facility programming schedules vary',
    'ADCRR inmates assigned to community reentry center programming per classification and release plan; community walk-in not available.',
    'Personas en custodia de ADCRR asignadas a programación del centro de reinserción comunitaria según clasificación y plan de liberación; no hay admisión comunitaria sin cita.',
    'Programming accessed through ADCRR classification and facility reentry staff; public overview at corrections.az.gov/adcr/community-reentry.',
    'La programación se accede a través de clasificación ADCRR y personal de reinserción de la instalación; descripción pública en corrections.az.gov.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Transitional programming', 'Employment readiness', 'Cognitive programming', 'Community partner linkage', 'Pre-release coordination'],
