  (
    'dd000001-0020-4000-8000-000000000001',
    'DES — Benefits Information Line',
    'The Arizona Department of Economic Security Benefits Information Line connects residents to SNAP, AHCCCS Medicaid, TANF cash assistance, and child care subsidy programs administered through county DES offices in all 15 counties. Returning citizens can call for application status, interview scheduling, and document guidance before visiting their county office in person. Phone and referral support—not a walk-in office.',
    'La Línea de Información de Beneficios del Departamento de Seguridad Económica de Arizona conecta a residentes con programas SNAP, Medicaid AHCCCS, asistencia en efectivo TANF y subsidios de cuidado infantil administrados a través de oficinas DES del condado en los 15 condados. Apoyo telefónico y de referencia, no una oficina presencial.',
    'c1000001-0009-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '1789 W Jefferson Street',
    '1-855-432-7587',
    'https://des.az.gov',
    NULL,
    'Phone line business hours; online 24/7',
    'Arizona residents applying for or receiving DES benefits; criminal record generally not a barrier to SNAP and Medicaid.',
    'Residentes de Arizona que solicitan o reciben beneficios DES; los antecedentes penales generalmente no son barrera para SNAP y Medicaid.',
    'Call 1-855-432-7587; apply online at healthearizonaplus.gov; find county office at des.az.gov/find-your-local-office.',
    'Llame al 1-855-432-7587; solicite en healthearizonaplus.gov; encuentre oficina del condado en des.az.gov.',
    ARRAY[]::TEXT[],
    'statewide',
