  (
    'dd000001-0021-4000-8000-000000000001',
    'UMOM New Day Centers',
    'UMOM New Day Centers is one of Arizona''s largest providers of family and single-adult homeless services in Maricopa County, operating emergency shelter, rapid rehousing, and transitional housing with case management for parents and individuals returning from incarceration. Housing navigators connect residents to DES benefits, ARIZONA@WORK, and Valleywise Health while stabilizing leases across the Phoenix metro. Family and adult shelter intake—not a general cash assistance office.',
    'UMOM New Day Centers es uno de los mayores proveedores de servicios para personas sin hogar familiares y adultos solteros en el condado Maricopa, operando refugio de emergencia, realojamiento rápido y vivienda transicional con manejo de casos para padres e individuos que regresan de la encarcelación.',
