    'A New Leaf — Family & Support Services',
    'A New Leaf provides domestic violence shelter, family support, homeless services, and financial literacy programs from its Mesa headquarters serving Maricopa County families including justice-involved parents reunifying with children. Distinct from rapid rehousing sites, the University Drive campus coordinates shelter, counseling, and DES benefits navigation for vulnerable households. Direct family services—not state probation reporting.',
    'A New Leaf ofrece refugio contra violencia doméstica, apoyo familiar, servicios para personas sin hogar y programas de alfabetización financiera desde su sede en Mesa sirviendo a familias del condado Maricopa incluidos padres con antecedentes penales que se reunifican con sus hijos.',
