  (
    'dd000001-0023-4000-8000-000000000001',
    'St. Joseph the Worker',
    'St. Joseph the Worker helps justice-involved and homeless job seekers in Maricopa County obtain dignified employment through job development, employer partnerships, clothing and tool assistance, and the MentorWORKS peer mentoring program. Employment specialists place clients with fair-chance employers across the Phoenix metro and coordinate with ARIZONA@WORK and community corrections. Employment-focused—not a housing or benefits office.',
    'St. Joseph the Worker ayuda a buscadores de empleo con antecedentes penales y sin hogar en el condado Maricopa a obtener empleo digno a través de desarrollo laboral, alianzas con empleadores y el programa de mentoría entre pares MentorWORKS.',
