    'Adultos listos para trabajar en el condado Maricopa incluidas personas con antecedentes penales y sin hogar; servicios de empleo gratuitos.',
    'Call 602-264-8951; walk-in employment services; pairs with Phoenix Rescue Mission and UMOM.',
