    'dd000001-0024-4000-8000-000000000001',
    'Phoenix Rescue Mission',
    'Phoenix Rescue Mission provides emergency shelter, addiction recovery, workforce development, and reentry support for men and women experiencing homelessness and justice involvement in Maricopa County through its Changing Lives Center and Hope for Hunger Food Bank. Chaplaincy-based recovery and life transformation programs connect graduates to St. Joseph the Worker and ARIZONA@WORK. Faith-based recovery and shelter—not a government benefits office.',
    'Phoenix Rescue Mission ofrece refugio de emergencia, recuperación de adicciones, desarrollo de la fuerza laboral y apoyo de reinserción para hombres y mujeres sin hogar y con antecedentes penales en el condado Maricopa a través de su Changing Lives Center.',
