    'dd000001-0025-4000-8000-000000000001',
    'Native American Connections',
    'Native American Connections operates behavioral health, housing, and supportive services for individuals and families including justice-involved Native and non-Native adults in Maricopa County through scattered-site housing, SAGE recovery housing, and outpatient behavioral health at the Patina Wellness Center. Staff coordinate with AHCCCS RBHA plans, ARIZONA@WORK, and tribal reentry partners. Housing and behavioral health—not a tribal enrollment office.',
    'Native American Connections opera salud conductual, vivienda y servicios de apoyo para individuos y familias incluidos adultos con antecedentes penales en el condado Maricopa a través de vivienda dispersa, vivienda de recuperación SAGE y salud conductual ambulatoria.',
