  (
    'dd000001-0028-4000-8000-000000000001',
    'Mountain Park Health Center',
    'Mountain Park Health Center operates Federally Qualified Health Center clinics across Maricopa County providing primary care, dental, behavioral health, and pharmacy services with sliding fees for uninsured patients including returning citizens. The Tempe-Baseline clinic serves central metro neighborhoods with AHCCCS and Medicare acceptance and same-day sick visits. FQHC medical home—not an emergency room or benefits office. This resource supports Arizonans navigating reentry in Maricopa County.',
    'Mountain Park Health Center opera clínicas FQHC en el condado Maricopa ofreciendo atención primaria, dental, salud conductual y farmacia con tarifas móviles para pacientes sin seguro incluidos ciudadanos que regresan. Este recurso apoya a arizonenses en reinserción en condado de Maricopa.',
