    'The ARIZONA@WORK Kingman office connects Mohave County job seekers including justice-involved adults from Kingman Regional Medical Center release and county jail to career coaching, WIOA referrals, and fair-chance employer navigation. Staff coordinate with Mohave County DES, Kingman Regional Medical Center, and rural reentry partners. Free workforce services—not emergency housing.',
    'La oficina ARIZONA@WORK de Kingman conecta buscadores de empleo del condado Mohave incluidos adultos con antecedentes penales con coaching de carrera, referencias WIOA y navegación de empleo de segunda oportunidad.',
