    'El Centro de Prevención del Suicidio La Frontera EMPACT ofrece intervención en crisis 24/7, equipos de crisis móviles y apoyo entre pares para residentes del condado Maricopa en crisis de salud conductual incluidas personas con antecedentes penales.',
