    'dd000001-0049-4000-8000-000000000001',
    'Apache County DES — Benefits & Family Support',
    'The Apache County DES Family Assistance Administration office in Show Low processes Nutrition Assistance (SNAP), Cash Assistance (TANF), and AHCCCS Medicaid eligibility applications for Arizona residents including returning citizens reestablishing food and health benefits after release from Apache County Jail or ADCRR custody. County DES staff help verify identity and income and accept applications submitted through Health-e-Arizona Plus.',
    'La oficina de Administración de Asistencia Familiar de DES del condado Apache en Show Low procesa solicitudes de Asistencia Nutricional (SNAP), Asistencia en Efectivo (TANF) y elegibilidad de Medicaid AHCCCS para residentes de Arizona, incluidos ciudadanos que regresan que restablecen beneficios alimentarios y de salud después de salir de la cárcel del condado Apache o de la custodia de ADCRR. El personal del condado ayuda a verificar identidad e ingresos y acepta solicitudes presentadas a través de Health-e-Arizona Plus.',
    'c1000001-0009-4000-8000-000000000001',
    'Arizona',
    'Apache',
    'Show Low',
