  (
    'dd000001-0063-4000-8000-000000000001',
    'A New Leaf — Rapid Rehousing',
    'A New Leaf Rapid Rehousing helps families and individuals experiencing homelessness in Maricopa County—including parents returning from incarceration—move quickly into permanent housing with short-term rental assistance and case management. Housing specialists connect participants to DES benefits, ARIZONA@WORK, and Valleywise Health while stabilizing leases across the East Valley. This resource supports Arizonans navigating reentry in Maricopa County.',
    'A New Leaf Rapid Rehousing ayuda a familias y personas sin hogar en el condado Maricopa—incluidos padres que regresan de la encarcelación—a trasladarse rápidamente a vivienda permanente con asistencia de alquiler a corto plazo y manejo de casos. Este recurso apoya a arizonenses en reinserción en condado de Maricopa.',
    'c1000001-0002-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Mesa',
    '4340 E Cotton Lane',
    '480-833-9200',
    'https://turnanewleaf.org',
    NULL,
    'Monday–Friday business hours',
    'Homeless Maricopa County households meeting HUD rapid rehousing criteria; justice-involved families welcome per program policy.',
    'Hogares sin hogar del condado Maricopa que cumplan criterios HUD de realojamiento rápido; familias con antecedentes penales bienvenidas según política.',
    'Call 480-833-9200 for housing intake; pairs with UMOM and St. Mary''s Food Bank.',
    'Llame al 480-833-9200 para admisión de vivienda.',
    ARRAY['Maricopa'],
