    'House of Refuge provides structured transitional housing, life skills training, and employment support for single mothers and families experiencing homelessness in Maricopa County including justice-involved women reunifying with children after release from Perryville or county jail. Case managers connect residents to ARIZONA@WORK, DES benefits, and Valleywise primary care. Family-focused transitional housing—not emergency walk-in shelter.',
    'House of Refuge ofrece vivienda transicional estructurada, capacitación en habilidades para la vida y apoyo laboral para madres solteras y familias sin hogar en el condado Maricopa incluidas mujeres con antecedentes penales que se reunifican con sus hijos después de la liberación.',
