    'dd000001-0065-4000-8000-000000000001',
    'CASS — Central Arizona Shelter Services',
    'Central Arizona Shelter Services operates the largest emergency shelter and rehousing system in Maricopa County, providing single-adult shelter, coordinated entry, and rapid rehousing for justice-involved adults experiencing homelessness in Phoenix. CASS navigators connect clients to ARIZONA@WORK, Community Bridges, and DES benefits through the Maricopa regional continuum of care.',
    'Central Arizona Shelter Services opera el mayor sistema de refugio de emergencia y realojamiento en el condado Maricopa, proporcionando refugio para adultos solteros y realojamiento rápido para adultos con antecedentes penales sin hogar en Phoenix.',
