    'Gospel Rescue Mission Tucson provides emergency shelter, addiction recovery, and workforce programs for homeless men and women in Pima County including justice-involved adults through faith-based life transformation programming. Graduates connect to Pima County One-Stop, CODAC, and Primavera housing partners. Faith-based shelter—not county probation.',
