  -- source id: 67
  (
    'dd000001-0067-4000-8000-000000000001',
    'MANA House — Veterans Transitional Housing',
    'MANA House — Veterans Transitional Housing serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. MANA House provides transitional housing and peer support for homeless and justice-involved veterans in Maricopa County through U.S. VETS and community partners, connecting residents to VA benefits, ARIZONA@WORK veteran staff, and permanent housing. Veteran-focused housing—not a general population emergency shelter. VA eligibility and discharge status affect which benefits apply; ask specifically for justice-involved veteran or VJO/HCRV services when calling. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'MANA House — Veterans Transitional Housing sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. La elegibilidad del VA y el tipo de baja afectan qué beneficios aplican; pida específicamente servicios VJO/HCRV o para veteranos en el sistema de justicia al llamar. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0014-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '755 E Willetta Street',
    '602-263-5531',
    'https://www.usvetsinc.org',
    NULL,
    'Residential 24/7; office Monday–Friday',
    'Homeless veterans in Maricopa County; justice-involved veterans per program policy; DD-214 or veteran status required.',
    'Veteranos sin hogar en el condado Maricopa; veteranos con antecedentes penales según política; se requiere DD-214 o estatus de veterano.',
    'Call 602-263-5531; coordinated with Arizona DVS county veterans service officers.',
    'Llame al 602-263-5531; coordinado con oficiales de servicios para veteranos del condado DVS.',
    ARRAY['Maricopa'],
    'single',
    ARRAY['Transitional housing', 'Support groups', 'Benefits navigation', 'Partner referrals', 'Permanent housing planning'],
