  -- source id: 68
  (
    'dd000001-0068-4000-8000-000000000001',
    'Adelante Healthcare — Mesa',
    'Adelante Healthcare — Mesa is a statewide or regional referral resource for Arizonans affected by the criminal justice system. Adelante Healthcare operates community health centers in Maricopa and Pinal counties with primary care, behavioral health, and dental services including sliding-fee care for uninsured justice-involved patients. The Mesa clinic coordinates AHCCCS enrollment with DES and referrals from Community Bridges and ADCRR reentry staff. Users can search by location, service type, or need to find active providers in Maricopa, and Pinal counties. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'Adelante Healthcare — Mesa es un recurso de referencia estatal o regional para arizonenses afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en los condados Maricopa y Pinal. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
    'c1000001-0004-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Mesa',
    '1661 E Camelback Road',
    '480-964-3922',
    'https://www.adelantehealthcare.com',
    NULL,
    'Clinic Monday–Friday',
    'Uninsured and Medicaid patients in Maricopa County; sliding fee scale available.',
    'Pacientes sin seguro y Medicaid en el condado Maricopa; escala de tarifa móvil disponible.',
    'Call 480-964-3922; multiple east valley locations; enroll at healthearizonaplus.gov.',
    'Llame al 480-964-3922; múltiples ubicaciones del este del valle.',
    ARRAY['Maricopa', 'Pinal'],
    'multi',
    ARRAY['Primary medical care', 'Behavioral health services', 'AHCCCS enrollment support'],
    ARRAY['mesa', 'maricopa', 'healthcare', 'FQHC', 'dental', 'reentry'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 69
  (
    'dd000001-0069-4000-8000-000000000001',
    'Chiricahua Community Health Centers — Sierra Vista',
    'Chiricahua Community Health Centers — Sierra Vista serves justice-involved adults and families rebuilding stability after incarceration in Cochise County. Chiricahua Community Health Centers provide Federally Qualified Health Center primary care, behavioral health, and pharmacy services for Cochise County residents including justice-involved adults returning from ADCRR and county jail with sliding-fee and AHCCCS acceptance. Services are available on a sliding fee or Medicaid basis for eligible patients; bring ID and release paperwork when establishing care after incarceration. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Chiricahua Community Health Centers — Sierra Vista sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Cochise. Los servicios están disponibles con tarifa móvil o Medicaid para pacientes elegibles; lleve identificación y documentos de liberación al establecer atención después de la encarcelación. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0004-4000-8000-000000000001',
    'Arizona',
    'Cochise',
    'Sierra Vista',
    '10566 N Highway 90',
    '520-459-7790',
    'https://www.cchci.org',
    NULL,
    'Clinic Monday–Friday',
