  -- source id: 70
  (
    'dd000001-0070-4000-8000-000000000001',
    'Community Medical Services — Phoenix MAT',
    'Community Medical Services — Phoenix MAT serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Community Medical Services operates opioid treatment programs with medication-assisted treatment at multiple Maricopa County clinics for justice-involved adults referred from drug courts, ADCRR, and Community Bridges. AHCCCS and cash-pay options support daily dosing and counseling. Treatment may require assessment, insurance or Medicaid enrollment, and referral from courts or corrections for some beds—call intake to confirm openings. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Community Medical Services — Phoenix MAT sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. El tratamiento puede requerir evaluación, seguro o Medicaid y referencia de tribunales o correcciones para algunas plazas—llame a admisión para confirmar disponibilidad. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0005-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '2301 W Northern Avenue',
    '602-866-1475',
