    'dd000001-0073-4000-8000-000000000001',
    'Southern Arizona Legal Aid — Tucson',
    'Southern Arizona Legal Aid — Tucson serves justice-involved adults and families rebuilding stability after incarceration in 5 Arizona counties. Southern Arizona Legal Aid provides free civil legal assistance to low-income residents of Pima, Santa Cruz, Cochise, and surrounding counties including housing, benefits, and limited record relief for justice-involved clients—not criminal defense. Representation is limited to civil legal matters—not active criminal cases. Income, household size, and offense type determine eligibility for record relief. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Southern Arizona Legal Aid — Tucson ofrece asistencia legal civil gratuita o de bajo costo para residentes de bajos ingresos en 5 condados de Arizona. Los abogados ayudan con sellado o eliminación de antecedentes, desalojos, beneficios y otros asuntos civiles—no casos penales activos. La representación se limita a asuntos legales civiles—no casos penales activos. Ingresos, tamaño del hogar y tipo de delito determinan la elegibilidad para alivio de antecedentes. Contacte la oficina para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
