    'Volunteer Lawyers Program — Maricopa County',
    'Volunteer Lawyers Program — Maricopa County serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. The Maricopa County Volunteer Lawyers Program connects low-income residents to pro bono attorneys for civil matters including family law, housing, and consumer issues through the Maricopa County Bar Foundation—not criminal defense or full-scope CLS replacement. Representation is limited to civil legal matters—not active criminal cases. Income, household size, and offense type determine eligibility for record relief. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
