    'ARIZONA@WORK — Phoenix Metro serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. The ARIZONA@WORK Phoenix Metro center on Van Buren Street connects central Phoenix job seekers including justice-involved adults to WIOA training, career fairs, and fair-chance employer partnerships through the Maricopa County workforce board. Staff help justice-involved job seekers build work history, remove record-related barriers, and connect to fair-chance employers in the region. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
