    'ARIZONA@WORK — Flagstaff',
    'ARIZONA@WORK — Flagstaff is a statewide or regional referral resource for Arizonans affected by the criminal justice system. ARIZONA@WORK Flagstaff connects Coconino County job seekers including justice-involved adults from northern Arizona correctional releases to career coaching, WIOA referrals, and rural fair-chance employment navigation. Users can search by location, service type, or need to find active providers in Coconino County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
