    'dd000001-0080-4000-8000-000000000001',
    'ID Theft Resource — Arizona Attorney General',
    'ID Theft Resource — Arizona Attorney General serves justice-involved adults and families rebuilding stability after incarceration in throughout Arizona. The Arizona Attorney General Identity Theft Resource Unit helps victims—including justice-involved individuals whose identity was compromised—restore credit, dispute fraudulent records, and obtain guidance on replacing identification documents needed for MVD and DES applications. Fees, proof of identity, and residency documents apply; reentry resources and legal aid partners often help gather required paperwork. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'ID Theft Resource — Arizona Attorney General sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en en todo Arizona. Aplican tarifas, prueba de identidad y documentos de residencia; recursos de reinserción y aliados legales suelen ayudar a reunir el papeleo requerido. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
