    'Arizona Transformation Project',
    'Arizona Transformation Project serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. The Arizona Transformation Project provides reentry mentoring, family reunification support, and community navigation for justice-involved men and women returning to Maricopa County through volunteer mentors and partnerships with St. Joseph the Worker and Community Bridges. Coalition and navigator resources connect returning citizens to local partners—they rarely provide emergency shelter, cash aid, or 24/7 crisis response on their own. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Arizona Transformation Project sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Las coaliciones y recursos de navegación conectan a ciudadanos que regresan con aliados locales—rara vez ofrecen refugio de emergencia, efectivo o respuesta de crisis 24/7 por sí solos. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
