    'dd000001-0102-4000-8000-000000000001',
    'Maricopa Community Colleges — Adult Education',
    'Maricopa Community Colleges — Adult Education serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Maricopa Community Colleges Adult Education provides free GED and High School Equivalency preparation, English language classes, and citizenship instruction at campuses across Maricopa County for returning citizens rebuilding credentials for ARIZONA@WORK and employer requirements. Classes are typically free or low-cost for Arizona adults; orientation may be required before enrollment in GED or vocational tracks. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Maricopa Community Colleges — Adult Education sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Las clases suelen ser gratuitas o de bajo costo para adultos en Arizona; puede requerirse orientación antes de inscribirse en GED o capacitación vocacional. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
