  (
    'dd000001-0108-4000-8000-000000000001',
    'Valley Metro — Reduced Fare & ADA Paratransit',
    'Valley Metro — Reduced Fare & ADA Paratransit serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Valley Metro provides public transit, reduced fares for seniors and people with disabilities, and ADA paratransit (Dial-a-Ride) across Maricopa County helping justice-involved adults reach probation appointments, ARIZONA@WORK, and medical visits. Reduced-fare resources typically require application and proof of income or disability; IDs are needed to receive a pass or card. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Valley Metro — Reduced Fare & ADA Paratransit sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Los recursos de tarifa reducida suelen requerir solicitud y prueba de ingresos o discapacidad; se necesita identificación para recibir un pase o tarjeta. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
