  (
    'dd000001-0109-4000-8000-000000000001',
    'Community Legal Services — Mesa Office',
    'Community Legal Services — Mesa Office serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Community Legal Services Mesa office provides free civil legal aid to low-income east valley residents including housing, public benefits, and record relief matters for justice-involved clients in Maricopa County—not criminal defense. Representation is limited to civil legal matters—not active criminal cases. Income, household size, and offense type determine eligibility for record relief. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Community Legal Services — Mesa Office ofrece asistencia legal civil gratuita o de bajo costo para residentes de bajos ingresos en condado de Maricopa. Los abogados ayudan con sellado o eliminación de antecedentes, desalojos, beneficios y otros asuntos civiles—no casos penales activos. La representación se limita a asuntos legales civiles—no casos penales activos. Ingresos, tamaño del hogar y tipo de delito determinan la elegibilidad para alivio de antecedentes. Contacte la oficina para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0006-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Mesa',
    '714 West Southern Avenue',
    '1-800-852-9075',
    'https://www.clsaz.org',
    NULL,
    'Monday–Friday business hours',
    'Low-income Maricopa County residents; LSC income limits; civil matters only.',
    'Residentes de bajos ingresos del condado Maricopa; límites de ingresos LSC; solo asuntos civiles.',
    'Apply at clsaz.org or call 1-800-852-9075; east valley satellite office.',
