    'dd000001-0111-4000-8000-000000000001',
    'Community Legal Services — Yuma Office',
    'Community Legal Services — Yuma Office serves justice-involved adults and families rebuilding stability after incarceration in Yuma County. The Community Legal Services Yuma office provides free civil legal aid to low-income Yuma County residents including agricultural workers and justice-involved clients with housing, benefits, and family law needs. Representation is limited to civil legal matters—not active criminal cases. Income, household size, and offense type determine eligibility for record relief. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Community Legal Services — Yuma Office ofrece asistencia legal civil gratuita o de bajo costo para residentes de bajos ingresos en condado de Yuma. Los abogados ayudan con sellado o eliminación de antecedentes, desalojos, beneficios y otros asuntos civiles—no casos penales activos. La representación se limita a asuntos legales civiles—no casos penales activos. Ingresos, tamaño del hogar y tipo de delito determinan la elegibilidad para alivio de antecedentes. Contacte la oficina para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
