    'dd000001-0112-4000-8000-000000000001',
    'Arizona Recovered Citizens United',
    'Arizona Recovered Citizens United serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Arizona Recovered Citizens United organizes peer support, civic engagement, and reentry navigation for formerly incarcerated Arizonans in Maricopa County through mutual aid networks and partnerships with Arizona Transformation Project. Peer specialists with lived experience offer mentoring and recovery support; certification requirements vary by resource. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Arizona Recovered Citizens United sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Especialistas pares con experiencia vivida ofrecen mentoría y apoyo en recuperación; los requisitos de certificación varían según el recurso. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
