    'dd000001-0113-4000-8000-000000000001',
    'Mohave County Peer Support Center',
    'Mohave County Peer Support Center is a statewide or regional referral resource for Arizonans affected by the criminal justice system. Mohave County behavioral health peer support services connect justice-involved adults in rural Mohave County to certified peer specialists, recovery groups, and referrals to West Yavapai Guidance Clinic satellite and Kingman Regional Medical Center. Users can search by location, service type, or need to find active providers in Mohave County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'Mohave County Peer Support Center es un recurso de referencia estatal o regional para arizonenses afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en condado de Mohave. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
