    'Sun Tran — Tucson Paratransit',
    'Sun Tran — Tucson Paratransit serves justice-involved adults and families rebuilding stability after incarceration in Pima County. Sun Tran and Sun Van paratransit provide public bus service and ADA complementary paratransit for eligible Pima County riders including justice-involved adults traveling to probation, CODAC, and Pima County One-Stop appointments. Reduced-fare resources typically require application and proof of income or disability; IDs are needed to receive a pass or card. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Sun Tran — Tucson Paratransit sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Pima. Los recursos de tarifa reducida suelen requerir solicitud y prueba de ingresos o discapacidad; se necesita identificación para recibir un pase o tarjeta. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
