    'Arizona Center for Disability Law',
    'Arizona Center for Disability Law serves justice-involved adults and families rebuilding stability after incarceration in throughout Arizona. The Arizona Center for Disability Law provides free advocacy for Arizonans with disabilities including justice-involved individuals facing discrimination in employment, housing, and benefits access under the ADA and Arizona law. Representation is limited to civil legal matters—not active criminal cases. Income, household size, and offense type determine eligibility for record relief. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
