    'dd000001-0121-4000-8000-000000000001',
    'Florence Project — Immigrant Legal Services',
    'Florence Project — Immigrant Legal Services serves justice-involved adults and families rebuilding stability after incarceration in 5 Arizona counties. The Florence Project provides free legal services to detained and formerly detained immigrants in Arizona including justice-involved non-citizens facing deportation proceedings, with offices in Florence and Phoenix. Representation is limited to civil legal matters—not active criminal cases. Income, household size, and offense type determine eligibility for record relief. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
