    'Central Arizona College — Adult Education serves justice-involved adults and families rebuilding stability after incarceration in Pinal County. Central Arizona College Adult Education offers free GED and High School Equivalency preparation for Pinal County adults including justice-involved residents at Coolidge and Aravaipa campuses. Classes are typically free or low-cost for Arizona adults; orientation may be required before enrollment in GED or vocational tracks. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Central Arizona College — Adult Education sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Pinal. Las clases suelen ser gratuitas o de bajo costo para adultos en Arizona; puede requerirse orientación antes de inscribirse en GED o capacitación vocacional. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
