    'Arizona at Work White Mountains conecta buscadores de empleo en los condados Apache y Navajo—incluidos adultos con antecedentes penales liberados de ADCRR y cárceles del condado—con coaching de currículum, referencias de capacitación WIOA y navegación de empleo de segunda oportunidad. Servicios básicos de carrera gratuitos.',
