    'dd000001-0124-4000-8000-000000000001',
    'North Country HealthCare — Show Low',
    'North Country HealthCare''s Show Low clinic provides Federally Qualified Health Center primary care, behavioral health, dental services, and sliding-fee care for uninsured and Medicaid patients in Apache County including returning citizens establishing a medical home after release from ADCRR custody or county jail. FQHC services coordinate with DES Medicaid enrollment and Arizona at Work employment partners.',
    'La clínica Show Low de North Country HealthCare ofrece atención primaria FQHC, salud conductual, servicios dentales y atención con tarifa móvil para pacientes sin seguro y Medicaid en el condado Apache incluidos ciudadanos que regresan que establecen un hogar médico después de la liberación.',
