    'dd000001-0130-4000-8000-000000000001',
    'Arizona at Work — Greenlee County',
    'Arizona at Work — Greenlee County is a statewide or regional referral resource for Arizonans affected by the criminal justice system. Arizona at Work Greenlee County connects job seekers in Arizona''s smallest county—including justice-involved adults from ADCRR release—to resume coaching, WIOA training referrals, and fair-chance employment navigation in Clifton and Morenci. Staff coordinate with SEABHS, DES benefits, and southeastern Arizona workforce partners. Users can search by location, service type, or need to find active providers in Greenlee County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'Arizona at Work — Greenlee County es un recurso de referencia estatal o regional para arizonenses afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en condado de Greenlee. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
    'c1000001-0003-4000-8000-000000000001',
    'Arizona',
    'Greenlee',
    'Clifton',
