    'Abierto a buscadores de empleo del condado Greenlee incluidas personas con antecedentes penales.',
    'Register at arizonaatwork.com; call 928-865-4700; pairs with Greenlee County DES and SEABHS Safford.',
    'Regístrese en arizonaatwork.com; llame al 928-865-4700.',
    ARRAY['Greenlee'],
