  (
    'dd000001-0151-4000-8000-000000000001',
    'La Paz County — Housing & Community Development',
    'La Paz County — Housing & Community Development is a statewide or regional referral resource for Arizonans affected by the criminal justice system. La Paz County Community Development connects low-income residents in Parker and the Colorado River communities to emergency rental assistance, weatherization referrals, and homeless prevention resources for justice-involved adults returning to rural western Arizona. County office—not an emergency shelter. Users can search by location, service type, or need to find active providers in La Paz County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'La Paz County — Housing & Community Development es un recurso de referencia estatal o regional para arizonenses afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en condado de La Paz. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
