    'dd000001-0154-4000-8000-000000000001',
    'Maricopa County Adult Education',
    'Maricopa County Adult Education serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Maricopa County School Superintendent Adult Education programs provide free High School Equivalency and English language instruction at community sites across Maricopa County for justice-involved adults rebuilding education credentials after release from county jail or state prison. Classes are typically free or low-cost for Arizona adults; orientation may be required before enrollment in GED or vocational tracks. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Maricopa County Adult Education sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Las clases suelen ser gratuitas o de bajo costo para adultos en Arizona; puede requerirse orientación antes de inscribirse en GED o capacitación vocacional. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0013-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
