    'Coconino Community College — Adult Education',
    'Coconino Community College — Adult Education is a statewide or regional referral resource for Arizonans affected by the criminal justice system. Coconino Community College Adult Education offers free GED preparation and English language instruction for northern Arizona adults including justice-involved Flagstaff residents, with referrals from Coconino County Jail programs and North Country HealthCare. Users can search by location, service type, or need to find active providers in Coconino County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
