    'Society of St. Vincent de Paul Phoenix provides emergency food boxes, clothing, utility assistance, and furniture for low-income Maricopa County households including returning citizens reestablishing basic needs after incarceration. Vincentian volunteers operate neighborhood conferences and a central dining room—not a benefits application office. This resource supports Arizonans navigating reentry in Maricopa County.',
