    'dd000001-0159-4000-8000-000000000001',
    'Interfaith Community Services — Tucson',
    'Interfaith Community Services — Tucson serves justice-involved adults and families rebuilding stability after incarceration in Pima County. Interfaith Community Services provides emergency food, financial assistance, and basic needs navigation for low-income Pima County households including returning citizens, operating a food bank and utility assistance program in northwest Tucson. Availability varies by season and donations; call ahead when possible to confirm clothing, hygiene kits, or furniture pickup hours. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Interfaith Community Services — Tucson sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Pima. La disponibilidad varía según la temporada y donaciones; llame cuando sea posible para confirmar horarios de ropa, kits de higiene o muebles. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
