    'dd000001-0161-4000-8000-000000000001',
    'Arizona''s Children Association — Family Support',
    'Arizona''s Children Association — Family Support serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Arizona''s Children Association provides foster care, kinship support, and family preservation services for vulnerable Maricopa County families including justice-involved parents working toward reunification after CPS or criminal justice involvement. Case managers coordinate DES child care subsidies and housing partners. Family resources may require participation in treatment or parenting classes; custody status affects some reunification services. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Arizona''s Children Association — Family Support sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Los recursos familiares pueden requerir participación en tratamiento o clases de crianza; el estado de custodia afecta algunos servicios de reunificación. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
