    'dd000001-0162-4000-8000-000000000001',
    'Community Food Bank of Southern Arizona',
    'Community Food Bank of Southern Arizona serves justice-involved adults and families rebuilding stability after incarceration in Pima, Santa Cruz, Cochise, and Graham counties. Community Food Bank of Southern Arizona distributes groceries through partner agencies and direct programs across Pima, Santa Cruz, Cochise, and Graham counties for low-income households including returning citizens reestablishing food security after incarceration. Food assistance does not usually require a criminal-record disclosure; staff can help with SNAP applications and pantry locations by ZIP code. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Community Food Bank of Southern Arizona sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en los condados Pima, Santa Cruz, Cochise y Graham. La asistencia alimentaria generalmente no requiere declarar antecedentes penales; el personal puede ayudar con solicitudes SNAP y ubicaciones de despensas por código postal. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
