    'dd000001-0163-4000-8000-000000000001',
    'Maricopa County Recorder — Voter Registration & ID',
    'Maricopa County Recorder — Voter Registration & ID is a statewide or regional referral resource for Arizonans affected by the criminal justice system. The Maricopa County Recorder''s Office assists residents with voter registration, replacement voter ID cards, and guidance on restoring voting rights after felony convictions under Arizona law. Staff provide forms and referrals to Arizona MVD and Community Legal Services—not DMV licensing services. Users can search by location, service type, or need to find active providers in Maricopa County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'Maricopa County Recorder — Voter Registration & ID es un recurso de referencia estatal o regional para arizonenses afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en condado de Maricopa. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
