  (
    'dd000001-0164-4000-8000-000000000001',
    'DNA People''s Legal Services — Flagstaff Office',
    'DNA People''s Legal Services — Flagstaff Office serves justice-involved adults and families rebuilding stability after incarceration in Coconino, Navajo, and Apache counties. DNA People''s Legal Services Flagstaff office provides free civil legal assistance to low-income residents of Coconino, Navajo, and Apache counties including public benefits, housing, and family law for justice-involved clients on tribal and non-tribal lands—not criminal defense. Representation is limited to civil legal matters—not active criminal cases. Income, household size, and offense type determine eligibility for record relief. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'DNA People''s Legal Services — Flagstaff Office ofrece asistencia legal civil gratuita o de bajo costo para residentes de bajos ingresos en los condados Coconino, Navajo y Apache. Los abogados ayudan con sellado o eliminación de antecedentes, desalojos, beneficios y otros asuntos civiles—no casos penales activos. La representación se limita a asuntos legales civiles—no casos penales activos. Ingresos, tamaño del hogar y tipo de delito determinan la elegibilidad para alivio de antecedentes. Contacte la oficina para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
