    'ADCRR — Kingman Community Corrections',
    'ADCRR — Kingman Community Corrections is a statewide or regional referral resource for Arizonans affected by the criminal justice system. The ADCRR Kingman Community Corrections office supervises parolees and probationers in Mohave County, coordinating referrals to Mohave County ARIZONA@WORK, Kingman DES office, and regional behavioral health providers for justice-involved adults under state supervision. Users can search by location, service type, or need to find active providers in Mohave County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
