    'dd000001-0166-4000-8000-000000000001',
    'ADCRR — Florence Complex Reentry Coordination',
    'ADCRR — Florence Complex Reentry Coordination serves justice-involved adults and families rebuilding stability after incarceration in Pinal, Maricopa, and Pima counties. ADCRR staff at Arizona State Prison Complex Florence coordinate pre-release reentry planning and community corrections handoffs for individuals returning to Pinal, Maricopa, and Pima counties, connecting supervisees to ARIZONA@WORK, DES benefits, and local housing partners. This office handles supervision compliance and reporting—not emergency reentry navigation; ask your officer for referrals to local reentry partners. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'ADCRR — Florence Complex Reentry Coordination sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en los condados Pinal, Maricopa y Pima. Esta oficina maneja cumplimiento de supervisión e informes—no navegación de crisis de reinserción; pida a su oficial referencias a aliados locales de reinserción. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
