  (
    'dd000001-0167-4000-8000-000000000001',
    'Arizona Department of Housing — Homelessness & Rental Assistance',
    'Arizona Department of Housing — Homelessness & Rental Assistance serves justice-involved adults and families rebuilding stability after incarceration in throughout Arizona. The Arizona Department of Housing administers statewide homelessness prevention, emergency rental assistance, and affordable housing programs that justice-involved Arizonans may access through regional housing navigators and coordinated entry systems in Maricopa, Pima, and rural counties. State offices provide information and referrals statewide; county and nonprofit partners deliver most direct services. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Arizona Department of Housing — Homelessness & Rental Assistance sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en en todo Arizona. Las oficinas estatales ofrecen información y referencias en todo el estado; socios del condado y sin fines de lucro prestan la mayoría de servicios directos. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
