    'dd000001-0168-4000-8000-000000000001',
    'Arizona Attorney General — Victim Services',
    'Arizona Attorney General — Victim Services is a statewide or regional referral resource for Arizonans affected by the criminal justice system. The Arizona Attorney General Victim Services Division provides crime victim compensation, restitution assistance, and referral navigation for eligible Arizonans including justice-involved crime victims and witnesses—not criminal defense representation. Users can search by location, service type, or need to find active providers in throughout Arizona. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'Arizona Attorney General — Victim Services es un recurso de referencia estatal o regional para arizonenses afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en en todo Arizona. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
    'c1000001-0001-4000-8000-000000000001',
