  (
    'dd000001-0169-4000-8000-000000000001',
    'Valley Metro — Reduced Fare & Reentry Transit',
    'Valley Metro — Reduced Fare & Reentry Transit serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Valley Metro provides public bus and light rail service across Maricopa County with reduced-fare passes for low-income riders including justice-involved adults returning from incarceration who need affordable transportation to ARIZONA@WORK, DES offices, and treatment appointments. Reduced-fare resources typically require application and proof of income or disability; IDs are needed to receive a pass or card. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Valley Metro — Reduced Fare & Reentry Transit sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Los recursos de tarifa reducida suelen requerir solicitud y prueba de ingresos o discapacidad; se necesita identificación para recibir un pase o tarjeta. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0010-4000-8000-000000000001',
