    'Service hours vary by route',
    'Maricopa County riders; reduced-fare programs for seniors, disabled, and low-income riders per Valley Metro policy.',
    'Pasajeros del condado Maricopa; programas de tarifa reducida para mayores, discapacitados y de bajos ingresos según política de Valley Metro.',
    'Call 602-253-5000; buy passes online or at light rail stations; not a paratransit medical broker.',
    'Llame al 602-253-5000; compre pases en línea o en estaciones de tren ligero.',
