    'dd000001-0170-4000-8000-000000000001',
    'Arizona Department of Veterans Services — Yuma County Office',
    'Arizona Department of Veterans Services — Yuma County Office is a statewide or regional referral resource for Arizonans affected by the criminal justice system. The Arizona Department of Veterans Services Yuma County office provides free VA benefits claims assistance, discharge upgrade guidance, and referral navigation for justice-involved veterans in Yuma and La Paz counties through the state county veterans service officer network. Users can search by location, service type, or need to find active providers in Yuma, and La Paz counties. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
