    'dd000001-0171-4000-8000-000000000001',
    'Arizona Department of Veterans Services — Coconino County Office',
    'Arizona Department of Veterans Services — Coconino County Office is a statewide or regional referral resource for Arizonans affected by the criminal justice system. The Arizona Department of Veterans Services Coconino County office assists northern Arizona veterans including justice-involved veterans in Flagstaff, Navajo, and Apache counties with VA disability claims, healthcare enrollment, and referrals to North Country HealthCare and ARIZONA@WORK Flagstaff. Users can search by location, service type, or need to find active providers in Coconino, Navajo, and Apache counties. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
