    'dd000001-0172-4000-8000-000000000001',
    'Arizona Department of Veterans Services — Mohave County Office',
    'Arizona Department of Veterans Services — Mohave County Office serves justice-involved adults and families rebuilding stability after incarceration in Mohave County. The Arizona Department of Veterans Services Mohave County office provides free VA claims assistance and benefits navigation for veterans in Kingman, Lake Havasu City, and Bullhead City including justice-involved veterans coordinating with Mohave County ARIZONA@WORK and regional behavioral health providers. VA eligibility and discharge status affect which benefits apply; ask specifically for justice-involved veteran or VJO/HCRV services when calling. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Arizona Department of Veterans Services — Mohave County Office sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Mohave. La elegibilidad del VA y el tipo de baja afectan qué beneficios aplican; pida específicamente servicios VJO/HCRV o para veteranos en el sistema de justicia al llamar. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
