    'dd000001-0173-4000-8000-000000000001',
    'United Food Bank — Emergency Food Distribution',
    'United Food Bank — Emergency Food Distribution serves justice-involved adults and families rebuilding stability after incarceration in Maricopa, Pinal, and Gila counties. United Food Bank distributes emergency groceries through partner pantries and direct programs across eastern Maricopa, Pinal, and Gila counties for low-income households including returning citizens reestablishing food security after incarceration. Availability varies by season and donations; call ahead when possible to confirm clothing, hygiene kits, or furniture pickup hours. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'United Food Bank — Emergency Food Distribution sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en los condados Maricopa, Pinal y Gila. La disponibilidad varía según la temporada y donaciones; llame cuando sea posible para confirmar horarios de ropa, kits de higiene o muebles. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
