    'dd000001-0174-4000-8000-000000000001',
    'Chicanos Por La Causa — Workforce & Education',
    'Chicanos Por La Causa — Workforce & Education serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Chicanos Por La Causa workforce and education programs offer GED preparation, digital literacy, and job training for Maricopa County adults including justice-involved participants referred from ARIZONA@WORK and community corrections partners. Classes are typically free or low-cost for Arizona adults; orientation may be required before enrollment in GED or vocational tracks. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Chicanos Por La Causa — Workforce & Education sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Las clases suelen ser gratuitas o de bajo costo para adultos en Arizona; puede requerirse orientación antes de inscribirse en GED o capacitación vocacional. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
