    'Literacy Volunteers of Maricopa County serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Literacy Volunteers of Maricopa County provides free adult literacy, ESL, and GED tutoring for low-literacy adults in Maricopa County including justice-involved learners rebuilding education skills after release from county jail or state prison. Classes are typically free or low-cost for Arizona adults; orientation may be required before enrollment in GED or vocational tracks. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
