    'Homeward Bound — Transitional Housing',
    'Homeward Bound — Transitional Housing serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. Homeward Bound provides transitional housing and supportive services for homeless families and single adults in Maricopa County including justice-involved parents reunifying with children, with case management connecting residents to ARIZONA@WORK and DES benefits. Resources may include case management, sobriety requirements, or referral from corrections partners—confirm admission steps before visiting. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Homeward Bound — Transitional Housing sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Maricopa. Los recursos pueden incluir manejo de casos, requisitos de sobriedad o referencia de socios correccionales—confirme los pasos de admisión antes de visitar. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
