    'dd000001-0178-4000-8000-000000000001',
    'Volunteer Lawyers Program — State Bar of Arizona',
    'Volunteer Lawyers Program — State Bar of Arizona serves justice-involved adults and families rebuilding stability after incarceration in Maricopa County. The State Bar of Arizona Volunteer Lawyers Program connects low-income Maricopa County residents including justice-involved clients to pro bono civil attorneys for housing, benefits, family law, and limited record relief matters—not criminal defense. Representation is limited to civil legal matters—not active criminal cases. Income, household size, and offense type determine eligibility for record relief. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Volunteer Lawyers Program — State Bar of Arizona ofrece asistencia legal civil gratuita o de bajo costo para residentes de bajos ingresos en condado de Maricopa. Los abogados ayudan con sellado o eliminación de antecedentes, desalojos, beneficios y otros asuntos civiles—no casos penales activos. La representación se limita a asuntos legales civiles—no casos penales activos. Ingresos, tamaño del hogar y tipo de delito determinan la elegibilidad para alivio de antecedentes. Contacte la oficina para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0006-4000-8000-000000000001',
    'Arizona',
    'Maricopa',
    'Phoenix',
    '4201 North 24th Street',
    '602-340-7323',
    'https://www.azvolunteerlawyers.org',
    NULL,
    'Monday–Friday business hours',
    'Low-income Maricopa County residents with civil legal needs; income screening required.',
    'Residentes de bajos ingresos del condado Maricopa con necesidades legales civiles; se requiere evaluación de ingresos.',
    'Apply at azvolunteerlawyers.org or call 602-340-7323; complements Community Legal Services.',
    'Solicite en azvolunteerlawyers.org o llame al 602-340-7323.',
    ARRAY['Maricopa'],
